mapper.update:
    	/** [sql-partsinput.xml] PartsInputMapper.updateOfPdStock **/
		UPDATE tb_st_01
		 -- 재고 차감 (출고등록/입고삭제)
		   SET st01_qty =  st01_qty - #{outQty}

		 -- 재고 증가 (입고등록/출고삭제)
		   SET st01_qty =  st01_qty + #{outQty}

		WHERE 1=1
		AND st01_company = #{company}
		AND st01_factory = '0001'
		AND st01_code = #{code}
		AND st01_stok = #{stock}

		   AND st01_lot = #{lot}
		   AND st01_lot_seq = #{lotSeq}

    	/** [sql-partsinput.xml] PartsInputMapper.updateOfSmdStock **/
		UPDATE tb_st_02
		 -- 재고 차감 (출고등록/입고삭제)
		   SET ST02_IPQTY =  ST02_IPQTY - #{outQty}

		 -- 재고 증가 (입고등록/출고삭제)
		   SET ST02_IPQTY =  ST02_IPQTY + #{outQty}

		WHERE 1=1
		AND ST02_COMPANY = #{company}
		AND ST02_FACTORY = '0001'
		AND ST02_CODE = #{code}
		AND ST02_STOK = #{stock}
		AND ST02_GBN = 'OC'

		   AND ST02_LOT = #{lot}
		   AND ST02_LOT_SEQ = #{lotSeq}
